const data = $input.first().json;

const staticData = $getWorkflowStaticData('global');
let sessionId = 'default_session';
if (typeof data.query === 'object' && data.query.sessionId) {
    sessionId = data.query.sessionId;
} else if (typeof data.query === 'string') {
    try {
        const parsed = JSON.parse(data.query);
        if (parsed.sessionId) sessionId = parsed.sessionId;
    } catch(e) {}
}
const context = (staticData.agentContext && staticData.agentContext[sessionId]) || '';
data.token = context || 'Bearer empty';

const cleanParams = {};
let rawParams = {};
if (typeof data.query === 'object') {
    rawParams = data.query.params || data.query;
} else if (typeof data.query === 'string') {
    try { rawParams = JSON.parse(data.query).params || JSON.parse(data.query); } catch(e) {}
}
for (const key in rawParams) {
  const val = rawParams[key];
  if (val !== null && val !== undefined && val !== '' && val !== 'null') {
    cleanParams[key] = val;
  }
}
data.cleanParams = cleanParams;
return [{ json: data }];

const responseData = $input.first().json;
let result = JSON.stringify(responseData);
if (responseData.data) { result = "Data: " + JSON.stringify(responseData.data); }
return [{ json: { response: result } }];
